def eval_rpn(tokens: list[str]) -> int:
    stack = []
    for token in tokens:
        if token in ["+", "-", "*", "/"]:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # token == "/"
                # Division truncates toward zero.
                # Using integer arithmetic to support arbitrarily large integers
                # and correct truncation behavior (towards zero).
                quotient = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    stack.append(-quotient)
                else:
                    stack.append(quotient)
        else:
            stack.append(int(token))
    return stack.pop()
