def calc(expr: str) -> float:
    i = 0
    n = len(expr)

    def skip_spaces():
        nonlocal i
        while i < n and expr[i] == ' ':
            i += 1

    def parse_number():
        nonlocal i
        start = i
        has_dot = False
        while i < n and (expr[i].isdigit() or (expr[i] == '.' and not has_dot)):
            if expr[i] == '.':
                has_dot = True
            i += 1
        return float(expr[start:i])

    def parse_factor():
        nonlocal i
        skip_spaces()
        sign = 1.0
        while i < n and expr[i] == '-':
            sign = -sign
            i += 1
            skip_spaces()

        if i < n and expr[i] == '(':
            i += 1
            res = parse_expr()
            skip_spaces()
            if i >= n or expr[i] != ')':
                raise ValueError("Unmatched parenthesis")
            i += 1
            return sign * res
        else:
            return sign * parse_number()

    def parse_term():
        nonlocal i
        result = parse_factor()
        while i < n and expr[i] in '*/':
            op = expr[i]
            i += 1
            skip_spaces()
            rhs = parse_factor()
            if op == '*':
                result *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                result /= rhs
        return result

    def parse_expr():
        nonlocal i
        result = parse_term()
        while i < n and expr[i] in '+-':
            op = expr[i]
            i += 1
            skip_spaces()
            rhs = parse_term()
            result = result + rhs if op == '+' else result - rhs
        return result

    result = parse_expr()
    skip_spaces()
    if i < n:
        raise ValueError("Unexpected characters at end of expression")
    return result
