import heapq
from collections import defaultdict

def sliding_median(nums: list[int], k: int) -> list[float]:
    lo = []  # max-heap (store negated values)
    hi = []  # min-heap
    delayed = defaultdict(int)
    balance = 0  # len(hi) - len(lo)

    def push(val):
        nonlocal balance
        if not lo or val <= -lo[0]:
            heapq.heappush(lo, -val)
            balance += 1
        else:
            heapq.heappush(hi, val)
            balance -= 1
        _bal()

    def _bal():
        nonlocal balance
        while balance > 1:
            heapq.heappush(hi, -heapq.heappop(lo))
            balance -= 1
        while balance < 0:
            heapq.heappush(lo, -heapq.heappop(hi))
            balance += 1

    def clean():
        nonlocal balance
        while lo and delayed[-lo[0]]:
            delayed[-lo[0]] -= 1
            balance += 1
            heapq.heappop(lo)
        while hi and delayed[hi[0]]:
            delayed[hi[0]] -= 1
            balance -= 1
            heapq.heappop(hi)

    for val in nums[:k]:
        push(val)

    res = []
    if k % 2 == 1:
        res.append(float(-lo[0]))
    else:
        res.append((-lo[0] + hi[0]) / 2.0)

    for i in range(k, len(nums)):
        out_num = nums[i - k]
        in_num = nums[i]

        if out_num <= -lo[0]:
            balance -= 1
        else:
            balance += 1

        delayed[out_num] += 1

        push(in_num)
        clean()

        if k % 2 == 1:
            res.append(float(-lo[0]))
        else:
            res.append((-lo[0] + hi[0]) / 2.0)

    return res
